// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 以訪客身分開始（FR-058）；已有 session 時直接回傳目前帳號
	// (POST /auth/guest)
	StartGuest(ctx context.Context, request StartGuestRequestObject) (StartGuestResponseObject, error)
	// 登入（FR-050、FR-053）
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// 登出目前裝置
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// 註冊（FR-050、FR-051、FR-060）。目前是訪客 session 時，直接把訪客升級為正式帳號
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// 用救援碼重設密碼（FR-051）
	// (POST /auth/reset-password)
	ResetPassword(ctx context.Context, request ResetPasswordRequestObject) (ResetPasswordResponseObject, error)
	// 建立小朋友檔案（US5 驗收 6）
	// (POST /children)
	CreateChild(ctx context.Context, request CreateChildRequestObject) (CreateChildResponseObject, error)
	// 刪除小朋友檔案與所有進度（FR-059、FR-062）；訪客不能使用
	// (DELETE /children/{childId})
	DeleteChild(ctx context.Context, request DeleteChildRequestObject) (DeleteChildResponseObject, error)
	// 修改暱稱或頭像
	// (PATCH /children/{childId})
	UpdateChild(ctx context.Context, request UpdateChildRequestObject) (UpdateChildResponseObject, error)
	// 由伺服器挑選寶可夢並產生題目（FR-035、FR-057）
	// (POST /children/{childId}/encounters)
	CreateEncounter(ctx context.Context, request CreateEncounterRequestObject) (CreateEncounterResponseObject, error)
	// 選擇夥伴（FR-040）；只能選一次
	// (POST /children/{childId}/partner)
	ChoosePartner(ctx context.Context, request ChoosePartnerRequestObject) (ChoosePartnerResponseObject, error)
	// 取得收集冊、夥伴、徽章、已開放區域等進度
	// (GET /children/{childId}/state)
	GetChildState(ctx context.Context, request GetChildStateRequestObject) (GetChildStateResponseObject, error)
	// 送出一題的作答結果；同樣內容重送只計算一次（FR-061）
	// (PUT /encounters/{encounterId}/answers/{questionIndex})
	SubmitAnswer(ctx context.Context, request SubmitAnswerRequestObject) (SubmitAnswerResponseObject, error)
	// 結算遭遇：星星、收服、經驗值、進化、區域開放、徽章；重送回傳同樣結果
	// (POST /encounters/{encounterId}/complete)
	CompleteEncounter(ctx context.Context, request CompleteEncounterRequestObject) (CompleteEncounterResponseObject, error)

	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
	// 刪除整個帳號（FR-059、FR-062）；訪客不能使用
	// (DELETE /me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// 取得目前帳號與所有小朋友檔案
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

